// =====================================================
// WEATHER DATA PROCESSOR
// Extract required fields from OpenWeather 3-hour blocks
// =====================================================

const list = msg.payload;

if (!Array.isArray(list) || list.length === 0) {
    node.warn("Invalid OpenWeather forecast data");
    return null;
}

// ---------------------------------------------
// Helper function
// ---------------------------------------------

function getRain(block) {
    if (block.rain && Number.isFinite(Number(block.rain["3h"]))) {
        return Number(block.rain["3h"]);
    }

    return 0;
}


// ---------------------------------------------
// Extract required weather fields
// ---------------------------------------------

const forecast = list.map(block => {

    return {
        dt: block.dt,

        pop: Number(block.pop || 0),

        rain: getRain(block),

        pressure: Number(
            block.main?.pressure || 0
        ),

        humidity: Number(
            block.main?.humidity || 0
        ),

        temp: Number(block.main.temp),

        clouds: Number(
            block.clouds?.all || 0
        ),

        speed: Number(
            block.wind?.speed || 0
        ),

        gust: Number(
            block.wind?.gust || 0
        )
    };

});


// ---------------------------------------------
// Store complete processed forecast
// ---------------------------------------------

flow.set("weatherForecast", forecast);


// ---------------------------------------------
// Keep the first 8 blocks = next ~24 hours
// ---------------------------------------------

const next24h = forecast.slice(0, 8);


// First 2 blocks = next ~6 hours
const next6h = forecast.slice(0, 2);


// ---------------------------------------------
// Send both forward
// ---------------------------------------------

msg.payload = {
    next6h: next6h,
    next24h: next24h
};

return msg;

const weather = msg.payload;

if (!weather || !weather.next6h || !weather.next24h) {
    return null;
}


// =====================================================
// 6-HOUR DATA
// Used for near-term monitoring
// =====================================================

const next6h = weather.next6h;

let maxPop6h = 0;
let totalRain6h = 0;

next6h.forEach(block => {

    maxPop6h = Math.max(maxPop6h, block.pop);

    totalRain6h += block.rain;

});


// =====================================================
// 24-HOUR DATA
// Used for prediction
// =====================================================

const next24h = weather.next24h;

let maxPop24h = 0;
let totalRain24h = 0;

next24h.forEach(block => {

    maxPop24h = Math.max(maxPop24h, block.pop);

    totalRain24h += block.rain;

});


// =====================================================
// CURRENT / NEXT FORECAST BLOCK
// =====================================================

const current = next6h[0];


// =====================================================
// FINAL DECISION INPUT
// =====================================================

msg.payload = {

    // Near-term rain
    rain_probability_6h: Number((maxPop6h * 100).toFixed(0)),
    rain_volume_6h: Number(totalRain6h.toFixed(2)),

    // 24-hour prediction
    rain_probability_24h: Number((maxPop24h * 100).toFixed(0)),
    rain_volume_24h: Number(totalRain24h.toFixed(2)),

    // Required weather parameters
    pressure: current.pressure,
    humidity: current.humidity,
    clouds: current.clouds,
    wind_speed: current.speed,
    wind_gust: current.gust,

    // Forecast timestamp
    dt: current.dt,

    // Human-readable timestamp
    forecast_time: new Date(current.dt * 1000).toISOString()

};



msg.payload.rain_expected_6h =
    msg.payload.rain_probability_6h > 60 || msg.payload.rain_volume_6h > 2;



flow.set('weatherForecast', msg.payload);
flow.set('weatherLastFetched', Date.now());

return msg;

const current = msg.payload;

if (!current) {
    return null;
}

const previous = flow.get("previousWeatherDecision");


// =====================================================
// FIRST WEATHER DATA
// =====================================================

if (!previous) {

    flow.set(
        "previousWeatherDecision",
        current
    );

    msg.payload = {
        changed: true,
        reason: "First weather data received",
        current: current
    };

    return msg;
}


// =====================================================
// PARAMETERS THAT MATTER
// =====================================================

const changed =
    previous.rain_probability_6h !== current.rain_probability_6h ||
    previous.rain_volume_6h !== current.rain_volume_6h ||

    previous.rain_probability_24h !== current.rain_probability_24h ||
    previous.rain_volume_24h !== current.rain_volume_24h ||

    previous.pressure !== current.pressure ||
    previous.humidity !== current.humidity ||
    previous.clouds !== current.clouds ||

    previous.wind_speed !== current.wind_speed ||
    previous.wind_gust !== current.wind_gust;


// =====================================================
// SAVE CURRENT DATA
// =====================================================

flow.set(
    "previousWeatherDecision",
    current
);


// =====================================================
// ONLY SEND WHEN IMPORTANT DATA CHANGED
// =====================================================

if (!changed) {
    return null;
}


msg.payload = {
    changed: true,
    previous: previous,
    current: current
};

return msg;

// Water Level Data Processor
// Validates the raw MQTT reading and rejects single-sample sensor glitches
// (HC-SR04 false echoes) using a rolling median filter, before producing
// a clean, timestamped value for the rest of the pipeline.

let level = Number(msg.payload);

// Reject anything that isn't a real, finite number
if (!Number.isFinite(level)) {
    node.warn("Water Level Data Processor: invalid payload received - " + msg.payload);
    return null;
}

// Clamp to the expected 0-100% range
if (level < 0) level = 0;
if (level > 100) level = 100;

// Rolling median over the last 5 readings — a single wild outlier gets
// outvoted by the surrounding normal readings, but a real sustained
// change still comes through within a couple of readings.
const WINDOW_SIZE = 5;
let buffer = context.get('levelBuffer') || [];

buffer.push(level);
if (buffer.length > WINDOW_SIZE) {
    buffer.shift();
}
context.set('levelBuffer', buffer);

const sorted = [...buffer].sort((a, b) => a - b);
const median = sorted[Math.floor(sorted.length / 2)];

msg.payload = {
    level: Number(median.toFixed(2)),
    level_instant: Number(level.toFixed(2)),   // the raw single reading, kept for reference
    ts: Date.now()
};

return msg;

// Water Level EMA Smoother
// Smooths the validated water level reading to reduce sensor noise
// before it reaches the rate calculator.

const raw = msg.payload.level;
const ts  = msg.payload.ts;

let ema = context.get('emaLevel');

if (ema === undefined) {
    ema = raw;   // first reading — start the average at the actual value
} else {
    ema = (0.3 * raw) + (0.7 * ema);
}

context.set('emaLevel', ema);

msg.payload = {
    level_raw: raw,
    level_ema: Number(ema.toFixed(2)),
    ts: ts
};

return msg;

// Water Level Rate Calculator
// Computes rate of change (%/min), with a guard against implausibly
// short gaps between messages (reconnect bursts, duplicate delivery)
// which would otherwise spike the rate to unrealistic values.

const raw = msg.payload.level_raw;
const ema = msg.payload.level_ema;
const ts = msg.payload.ts;

const previousLevel = context.get('prevLevel');
const previousTime = context.get('prevTime');
const lastRate = context.get('lastRate') || 0;

const MIN_GAP_MINUTES = 1 / 60;

let rate = lastRate;

if (previousLevel !== undefined && previousTime !== undefined) {
    const timeMinutes = (ts - previousTime) / 60000;

    if (timeMinutes >= MIN_GAP_MINUTES) {
        rate = (ema - previousLevel) / timeMinutes;

        context.set('prevLevel', ema);
        context.set('prevTime', ts);
        context.set('lastRate', rate);
    }
} else {
    context.set('prevLevel', ema);
    context.set('prevTime', ts);
    context.set('lastRate', 0);
    rate = 0;
}

msg.payload = {
    level_raw: raw,
    level_ema: ema,
    rate: Number(rate.toFixed(2)),
    ts: ts
};

return msg;

// =====================================================
// WATER RISK CLASSIFIER — WEATHER AWARE
// =====================================================

const ema = Number(msg.payload.level_ema);
const rate = Number(msg.payload.rate);

if (!Number.isFinite(ema) || !Number.isFinite(rate)) {
    return null;
}


// =====================================================
// GET LATEST WEATHER DATA
// =====================================================

const weather = flow.get("weatherForecast") || {};

const rainProb6h = Number(weather.rain_probability_6h || 0);
const rainVolume6h = Number(weather.rain_volume_6h || 0);

const rainProb24h = Number(weather.rain_probability_24h || 0);
const rainVolume24h = Number(weather.rain_volume_24h || 0);

const humidity = Number(weather.humidity || 0);
const clouds = Number(weather.clouds || 0);
const windSpeed = Number(weather.wind_speed || 0);
const windGust = Number(weather.wind_gust || 0);


// =====================================================
// WEATHER FRESHNESS GATE
// =====================================================

const WEATHER_STALE_THRESHOLD_MS = 20 * 60 * 1000; // 20 minutes
//const WEATHER_STALE_THRESHOLD_MS = 60 * 1000; // 1 minute

const weatherLastFetched = flow.get("weatherLastFetched");

const weatherAgeMs = weatherLastFetched
    ? Date.now() - weatherLastFetched
    : null;

const weatherIsStale =
    !weatherLastFetched ||
    weatherAgeMs > WEATHER_STALE_THRESHOLD_MS;

// Ignore weather influence when forecast data is stale.
// Raw weather values remain unchanged for display.
const effRainProb6h =
    weatherIsStale ? 0 : rainProb6h;

const effRainVolume6h =
    weatherIsStale ? 0 : rainVolume6h;

const effRainVolume24h =
    weatherIsStale ? 0 : rainVolume24h;

const effHumidity =
    weatherIsStale ? 0 : humidity;

const effClouds =
    weatherIsStale ? 0 : clouds;





// =====================================================
// BASE THRESHOLDS
// =====================================================

let levelWatch = 40;
let levelAlert = 60;
let levelCritical = 80;

let rateAlert = 3;
let rateCritical = 5;


// =====================================================
// WEATHER SEVERITY SCORE
// =====================================================

// Rain probability contribution
let weatherScore = 0;

if (effRainProb6h >= 80) weatherScore += 3;
else if (effRainProb6h >= 60) weatherScore += 2;
else if (effRainProb6h >= 40) weatherScore += 1;


// Rain volume contribution

if (effRainVolume6h >= 10) weatherScore += 3;
else if (effRainVolume6h >= 5) weatherScore += 2;
else if (effRainVolume6h >= 2) weatherScore += 1;


// 24-hour rainfall adds predictive context

if (effRainVolume24h >= 20) weatherScore += 2;
else if (effRainVolume24h >= 10) weatherScore += 1;


// Supporting weather conditions

if (effRainVolume24h >= 20) weatherScore += 2;
else if (effRainVolume24h >= 10) weatherScore += 1;




// =====================================================
// ADAPT THRESHOLDS
// =====================================================

if (weatherScore >= 6) {

    // Severe weather expected
    levelWatch = 30;
    levelAlert = 50;
    levelCritical = 70;

    rateAlert = 2;
    rateCritical = 4;

}
else if (weatherScore >= 4) {

    // Moderate weather risk
    levelWatch = 35;
    levelAlert = 55;
    levelCritical = 75;

    rateAlert = 2.5;
    rateCritical = 4.5;

}
else if (weatherScore >= 2) {

    // Mild weather risk
    levelWatch = 38;
    levelAlert = 58;
    levelCritical = 78;

    rateAlert = 2.8;
    rateCritical = 4.8;
}


// =====================================================
// FINAL WATER RISK
// =====================================================

let state = "NORMAL";

if (ema >= levelCritical || rate >= rateCritical) {

    state = "CRITICAL";

}
else if (ema >= levelAlert || rate >= rateAlert) {

    state = "ALERT";

}
else if (ema >= levelWatch || effRainProb6h >= 60) {

    state = "WATCH";

}


// =====================================================
// FLOAT SWITCH OVERRIDE
// =====================================================

if (flow.get("floatSwitchTripped")) {
    state = "CRITICAL";
}



// =====================================================
// OUTPUT
// =====================================================

msg.payload = {

    level: Number(ema.toFixed(2)),
    rate: Number(rate.toFixed(2)),

    state: state,

    weather_score: weatherScore,

    rain_probability_6h: rainProb6h,
    rain_volume_6h: rainVolume6h,

    rain_probability_24h: rainProb24h,
    rain_volume_24h: rainVolume24h,

    humidity: humidity,
    clouds: clouds,

    wind_speed: windSpeed,
    wind_gust: windGust,

    weather_adjusted: weatherScore > 0,

    weather_stale: weatherIsStale,
    weather_age_seconds: weatherAgeMs !== null ? Math.round(weatherAgeMs / 1000) : null,

    ts: msg.payload.ts
};

return msg;

if (msg.payload && msg.payload.state) {
    msg.payload = msg.payload.state;
    return msg;
}

return null;

const risk = msg.payload;

if (!risk || !risk.state) {
    return null;
}

msg.payload =
    "FLOOD RISK: " + risk.state +
    " | Water Level: " + Number(risk.level).toFixed(1) + "%" +
    " | Rise Rate: " + Number(risk.rate).toFixed(2) + "%/min";

return msg;

// Water Risk LED Command
// Maps the 4-level risk state down to the 3 physical LED colors on the ESP32,
// and publishes the command the ESP32's MQTT callback already listens for.

const state = msg.payload;

let color = "GREEN";

if (state === "CRITICAL") {
    color = "RED";
} else if (state === "ALERT") {
    color = "YELLOW";
} else {
    color = "GREEN";   // NORMAL and WATCH both stay green
}

msg.payload = color;
return msg;

// =====================================================
// RAIN-ADJUSTED TIME-TO-CRITICAL PREDICTOR
// =====================================================

const level = Number(msg.payload.level_ema);
const rate = Number(msg.payload.rate);

if (!Number.isFinite(level) || !Number.isFinite(rate)) {
    return null;
}


// -----------------------------------------------------
// GET LATEST WEATHER
// -----------------------------------------------------

const weather = flow.get("weatherForecast") || {};

const rainProb6h = Number(weather.rain_probability_6h || 0);
const rainVolume6h = Number(weather.rain_volume_6h || 0);


// -----------------------------------------------------
// BASE CRITICAL LEVEL
// -----------------------------------------------------

const CRITICAL_LEVEL = 80;


// -----------------------------------------------------
// CALCULATE BASE TIME TO CRITICAL
// -----------------------------------------------------

let baseTime = null;

if (rate > 0 && level < CRITICAL_LEVEL) {

    const remaining = CRITICAL_LEVEL - level;

    baseTime = remaining / rate;
}


// -----------------------------------------------------
// ESTIMATE RAIN IMPACT
// -----------------------------------------------------

let rainFactor = 1.0;

if (rainProb6h >= 80 || rainVolume6h >= 10) {

    rainFactor = 1.35;

}
else if (rainProb6h >= 60 || rainVolume6h >= 5) {

    rainFactor = 1.20;

}
else if (rainProb6h >= 40 || rainVolume6h >= 2) {

    rainFactor = 1.10;
}


// -----------------------------------------------------
// RAIN-ADJUSTED PREDICTION
// -----------------------------------------------------

let adjustedTime = null;

if (baseTime !== null) {

    adjustedTime = baseTime / rainFactor;
}


// -----------------------------------------------------
// ADD VALUES TO MESSAGE
// -----------------------------------------------------

msg.payload.time_to_critical_min =
    adjustedTime !== null
        ? Number(adjustedTime.toFixed(1))
        : null;

msg.payload.base_time_to_critical_min =
    baseTime !== null
        ? Number(baseTime.toFixed(1))
        : null;

msg.payload.rain_factor = rainFactor;

msg.payload.rain_probability_6h = rainProb6h;
msg.payload.rain_volume_6h = rainVolume6h;


// -----------------------------------------------------
// HUMAN-READABLE MESSAGE
// -----------------------------------------------------

if (level >= CRITICAL_LEVEL) {

    msg.payload.critical_prediction =
        "CRITICAL: Water level already at critical level";

}
else if (adjustedTime !== null && rainFactor > 1) {

    msg.payload.critical_prediction =
        "Rain-adjusted critical level in approximately " +
        adjustedTime.toFixed(1) +
        " minutes";

}
else if (adjustedTime !== null) {

    msg.payload.critical_prediction =
        "Critical level in approximately " +
        adjustedTime.toFixed(1) +
        " minutes";

}
else {

    msg.payload.critical_prediction =
        "Water level is not currently rising";

}


return msg;

// Weather Dashboard Formatter

const weather = msg.payload;

if (!weather || !weather.next6h || !weather.next6h.length) {
    return null;
}

const current = weather.next6h[0];

const rainProbability = Math.round(current.pop * 100);
const rainVolume = Number(current.rain).toFixed(1);
const humidity = current.humidity;
const windSpeed = Number(current.speed).toFixed(1);

msg.payload =
    `Rain: ${rainProbability}% (${rainVolume} mm) next 3h | ` +
    `Humidity: ${humidity}% | ` +
    `Wind: ${windSpeed} m/s`;

return msg;

// Time To Critical Dashboard

const prediction = msg.payload.critical_prediction;

if (!prediction) {
    return null;
}

// Store the latest prediction for the Risk State Cache.
flow.set('latestPrediction', prediction);

return null;

// Escalation Timer

const state = msg.payload;

// Clear timer when system returns to NORMAL
if (state === "NORMAL") {
    const existing = context.get("escalationTimer");

    if (existing) {
        clearTimeout(existing);
    }

    context.set("escalationTimer", null);
    flow.set("ackReceived", false);
    flow.set("lastEmailState", null);

    return null;
}


// Start timer only when entering ALERT
if (state === "ALERT") {

    const existing = context.get("escalationTimer");

    // Timer already running, do nothing
    if (existing) {
        return null;
    }

    // New ALERT episode
    flow.set("ackReceived", false);

    const timer = setTimeout(() => {

        if (!flow.get("ackReceived")) {

            node.send({
                payload: "ESCALATED: No acknowledgment received, treat as CRITICAL"
            });
        }

        context.set("escalationTimer", null);

    }, 60000);

    context.set("escalationTimer", timer);
}

return null;

// Email Alert Filter

const state = msg.payload;

// Only send email for ALERT or CRITICAL
if (state !== "ALERT" && state !== "CRITICAL") {
    return null;
}

// Prevent repeated emails for the same state
const last = flow.get("lastEmailState");

if (last === state) {
    return null;
}

flow.set("lastEmailState", state);

msg.topic = "Smart Drain Flood Alert - " + state;

msg.payload =
    "Flood risk state changed to " + state + ".\n\n" +
    "Please check the Smart Drain Monitoring dashboard for live water level, " +
    "weather conditions, prediction, and node status.";

return msg;

let log = flow.get('eventLog') || [];

const entry = {
    time: new Date().toLocaleTimeString(),
    state: msg.payload
};

log.unshift(entry);

if (log.length > 20) {
    log = log.slice(0, 20);
}

flow.set('eventLog', log);

msg.payload = log;

return msg;

const w = msg.payload;

if (!w) return null;

const current = w.next6h ? w.next6h[0] : w;

msg.payload = {

    rain_prob_6h: w.rain_probability_6h ?? Math.round((current.pop || 0) * 100),

    rain_vol_6h: w.rain_volume_6h ?? current.rain,

    rain_prob_24h: w.rain_probability_24h ?? null,

    rain_vol_24h: w.rain_volume_24h ?? null,

    humidity: current.humidity,

    temp: current.temp,

    clouds: current.clouds,

    wind_speed: current.speed ?? w.wind_speed,

    wind_gust: current.gust ?? w.wind_gust,

    pressure: current.pressure ?? w.pressure,

    // Temporary location field
    location:
    msg.location?.city && msg.location?.country
        ? `${msg.location.city}, ${msg.location.country}`
        : "Location unavailable"

};

return msg;

format:
/* =========================================================
   SMART DRAIN - DRAIN MONITOR
   LIGHT SAAS THEME - STEP 1
   ========================================================= */

:root {
    --sd-bg: #faf7f5;
    --sd-card: #ffffff;
    --sd-card-soft: #fcfbfa;

    --sd-text: #292725;
    --sd-text-secondary: #706d69;

    --sd-coral: #e85d4e;
    --sd-blue: #3b9fe0;
    --sd-green: #2fae7b;
    --sd-orange: #f0a93b;

    --sd-border: rgba(43, 42, 40, 0.06);

    --sd-radius: 24px;

    --sd-shadow:
        0 8px 30px rgba(40, 35, 30, 0.06),
        0 2px 8px rgba(40, 35, 30, 0.03);
}


/* PAGE BACKGROUND */

.v-main {
    background: var(--sd-bg) !important;
}


/* DASHBOARD GROUPS */

.nrdb-ui-group .v-card {
    background: var(--sd-card) !important;

    border-radius: var(--sd-radius) !important;

    border: 1px solid var(--sd-border) !important;

    box-shadow: var(--sd-shadow) !important;
}


/* GROUP TITLE */

.nrdb-ui-group .v-card-title,
.nrdb-ui-group-title {
    color: var(--sd-text) !important;

    font-weight: 700 !important;
}


/* GENERAL TEXT */

.nrdb-ui-group {
    color: var(--sd-text) !important;
}


/* SECONDARY TEXT */

.nrdb-ui-group .text-medium-emphasis {
    color: var(--sd-text-secondary) !important;
}


/* BUTTONS */

.nrdb-ui-group .v-btn {
    border-radius: 14px !important;

    text-transform: none !important;

    font-weight: 600 !important;
}


/* PRIMARY BUTTON */

.nrdb-ui-group .v-btn--variant-elevated {
    background: var(--sd-coral) !important;
}


/* HOVER */

.nrdb-ui-group .v-btn:hover {
    transform: translateY(-1px);

    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease;
}


/* SMOOTH CARD TRANSITION */

.nrdb-ui-group .v-card {
    transition:
        box-shadow 0.2s ease,
        transform 0.2s ease;
}


/* DESKTOP HOVER */

@media (min-width: 1024px) {

    .nrdb-ui-group .v-card:hover {
        box-shadow:
            0 12px 36px rgba(40, 35, 30, 0.08),
            0 3px 10px rgba(40, 35, 30, 0.03) !important;
    }

}



/* =========================================================
   SYSTEM STATUS - SENSOR NODE
   ========================================================= */

.sensor-status {
    background: #f8fffc !important;
    border: 1px solid rgba(47, 174, 123, 0.12) !important;
    border-radius: 14px !important;
    padding: 10px 14px !important;
    box-shadow: none !important;
    transition: none !important;
}


/* =========================================================
   SYSTEM STATUS - ACTUATOR NODE
   ========================================================= */


.actuator-status {
    background: #fffaf4 !important;
    border: 1px solid rgba(240, 169, 59, 0.14) !important;
    border-radius: 14px !important;
    padding: 10px 14px !important;
    box-shadow: none !important;
    transition: none !important;
}


/* =========================================================
   SYSTEM STATUS - CURRENT RISK
   ========================================================= */

.risk-status {
    margin-top: 6px !important;
    padding: 10px 14px !important;
    background: #FBF9F7 !important;
    border: 1px solid rgba(0, 0, 0, 0.05) !important;
    border-radius: 14px !important;
    box-shadow: none !important;
    font-weight: 600 !important;
}



/* =========================================================
   WATER LEVEL GAUGE
   ========================================================= */

.water-level-gauge {
    padding: 12px !important;
    border-radius: 20px !important;

    background: linear-gradient(
        145deg,
        #ffffff 0%,
        #f5fbfe 100%
    ) !important;

    border: 1px solid rgba(59, 159, 224, 0.10) !important;

    box-shadow:
        0 5px 20px rgba(40, 35, 30, 0.04) !important;

    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease !important;
}

.water-level-gauge:hover {
    transform: translateY(-1px);

    box-shadow:
        0 9px 26px rgba(40, 35, 30, 0.07) !important;
}


/* =========================================================
   WATER LEVEL HISTORY
   ========================================================= */

.water-history-chart {
    background: #ffffff !important;

    border: 1px solid rgba(59, 159, 224, 0.08) !important;

    border-radius: 20px !important;

    box-shadow:
        0 6px 24px rgba(40, 35, 30, 0.045) !important;

    overflow: hidden !important;

    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease !important;
}

.water-history-chart:hover {
    transform: translateY(-1px);

    box-shadow:
        0 10px 30px rgba(40, 35, 30, 0.065) !important;
}


/* =========================================================
   EVENTS & ALERTS
   ========================================================= */

.event-history {
    background: #ffffff !important;

    border: 1px solid rgba(232, 93, 78, 0.08) !important;

    border-radius: 22px !important;

    box-shadow:
        0 7px 26px rgba(40, 35, 30, 0.045) !important;

    overflow: hidden !important;
}

/* Event list */

.event-history hr {
    border: 0 !important;
    border-top: 1px solid rgba(43, 42, 40, 0.06) !important;
}

/* Scroll area */

.event-history ::-webkit-scrollbar {
    width: 7px;
}

.event-history ::-webkit-scrollbar-track {
    background: transparent;
}

