flow.set("ackReceived", true);

msg.payload = JSON.stringify({ ack: true, ts: Date.now() });
msg.topic = "team10/flood/zone1/actuator/led";
msg.payload="GREEN";
return msg;

// Trend Classifier
// Dashboard display only.
// Does not affect Risk Classifier or Prediction.

const rate = Number(msg.payload.rate);

if (!Number.isFinite(rate)) {
    return null;
}

const abs = Math.abs(rate);

let direction;
let label;

if (abs < 1) {
    direction = "stable";
    label = "Stable";
}
else if (rate > 0 && abs < 3) {
    direction = "rising";
    label = "Rising Slowly";
}
else if (rate > 0 && abs < 5) {
    direction = "rising";
    label = "Rising";
}
else if (rate > 0) {
    direction = "rising-fast";
    label = "Rising Rapidly";
}
else if (abs < 3) {
    direction = "falling";
    label = "Falling Slowly";
}
else if (abs < 5) {
    direction = "falling";
    label = "Falling";
}
else {
    direction = "falling-fast";
    label = "Falling Rapidly";
}

msg.payload = {
    rate: Number(rate.toFixed(2)),
    direction: direction,
    label: label
};

return msg;

// Risk Score Builder
// Derives a 0-100 display score + explanation from the existing
// Water Risk Classifier output. Does NOT alter or duplicate the
// classifier's decision — state is passed through untouched, and
// the score is hard-clamped to that state's band so it can never
// contradict it.

const level = Number(msg.payload.level);
const rate = Number(msg.payload.rate);
const state = msg.payload.state;
const weatherScore = Number(msg.payload.weather_score || 0);
const rainProb = Number(msg.payload.rain_probability_6h || 0);
const rainVol = Number(msg.payload.rain_volume_6h || 0);

if (!Number.isFinite(level) || !state) return null;

// ---- Reconstruct the same adaptive thresholds the classifier uses ----
// (mirrors Water Risk Classifier's logic — for scoring interpretation only,
// never used to decide state itself)
let levelWatch = 40, levelAlert = 60, levelCritical = 80;
let rateAlert = 3, rateCritical = 5;

if (weatherScore >= 6) {
    levelWatch = 30; levelAlert = 50; levelCritical = 70;
    rateAlert = 2; rateCritical = 4;
} else if (weatherScore >= 4) {
    levelWatch = 35; levelAlert = 55; levelCritical = 75;
    rateAlert = 2.5; rateCritical = 4.5;
} else if (weatherScore >= 2) {
    levelWatch = 38; levelAlert = 58; levelCritical = 78;
    rateAlert = 2.8; rateCritical = 4.8;
}

// ---- Band definitions for the DISPLAY score (fixed, independent of state logic) ----
const bands = {
    NORMAL: { min: 0, max: 39 },
    WATCH: { min: 40, max: 59 },
    ALERT: { min: 60, max: 79 },
    CRITICAL: { min: 80, max: 100 }
};

const band = bands[state] || bands.NORMAL;

// ---- Estimate position within the band using level + rate pressure ----
const levelPressure = Math.min(1, level / (levelCritical || 100));
const ratePressure = Math.min(1, Math.max(0, rate) / (rateCritical || 5));
const combinedPressure = Math.max(levelPressure, ratePressure); // whichever is more severe

let rawScore = band.min + combinedPressure * (band.max - band.min);

// Hard clamp — score can NEVER leave its state's band, no matter what
rawScore = Math.max(band.min, Math.min(band.max, rawScore));

const score = Math.round(rawScore);

// ---- Build human-readable factors dynamically from real values ----
function levelDescriptor(l) {
    if (l >= levelCritical) return "critical";
    if (l >= levelAlert) return "elevated";
    if (l >= levelWatch) return "moderate";
    return "normal";
}

function rateDescriptor(r) {
    const a = Math.abs(r);
    if (a < 1) return "stable";
    if (r > 0 && a >= rateCritical) return "rapid";
    if (r > 0 && a >= rateAlert) return "moderate";
    if (r > 0) return "slow";
    if (a >= rateCritical) return "falling rapidly";
    if (a >= rateAlert) return "falling";
    return "falling slowly";
}

function rainImpactDescriptor(prob) {
    if (prob >= 60) return "high impact";
    if (prob >= 40) return "moderate impact";
    if (prob >= 1) return "low impact";
    return "no impact";
}

const factors = [
    `Water level: ${level.toFixed(0)}% (${levelDescriptor(level)})`,
    `Rise rate: ${rate >= 0 ? '+' : ''}${rate.toFixed(1)}%/min (${rateDescriptor(rate)})`,
    `Rain forecast: ${rainProb}% probability, ${rainVol}mm (${rainImpactDescriptor(rainProb)})`
];

const recommendations = {
    NORMAL: "Continue monitoring.",
    WATCH: "Monitor rainfall and water level closely.",
    ALERT: "Inspect drain and prepare response.",
    CRITICAL: "Immediate field inspection required."
};

msg.payload = {
    score: score,
    state: state,
    factors: factors,
    recommendation: recommendations[state] || "Continue monitoring.",
    level: level,
    rate: rate
};

return msg;

// Risk State Cache — stores latest state for other branches to read

const state = msg.payload;
const prediction = flow.get('latestPrediction') || "Water level is not currently rising";

flow.set('currentRiskState', state);

msg.payload = {
    prediction: prediction,
    state: state
};

return msg;

// Sensor Data Freshness Checker

const now = Date.now();

// Periodic freshness check
if (msg.topic === "freshness_check") {

    const lastReading = flow.get("lastWaterLevelReading");

    if (!lastReading) {
        msg.payload = {
            status: "STALE",
            age_seconds: null
        };
    } else {
        const ageSeconds = (now - lastReading) / 1000;

        msg.payload = {
            status: ageSeconds > 15 ? "STALE" : "FRESH",
            age_seconds: Number(ageSeconds.toFixed(1))
        };
    }

    return msg;
}

// Normal water-level MQTT reading
const level = Number(msg.payload);

if (!Number.isFinite(level)) {
    return null;
}

flow.set("lastWaterLevelReading", now);

return null;

// Sensor Node Status Display

// Current MQTT connection state
let connectionState = flow.get("sensorConnectionState") || "OFFLINE";

// Current sensor-data freshness
let dataState = flow.get("sensorDataFreshness") || "UNKNOWN";

// Handle sensor node connection status
if (msg.topic === "team10/flood/zone1/node_status") {

    connectionState =
        (msg.payload === "online")
            ? "ONLINE"
            : "OFFLINE";

    flow.set("sensorConnectionState", connectionState);
}

// Handle sensor-data freshness
else if (
    msg.topic === "freshness_check" &&
    msg.payload &&
    msg.payload.status
) {

    dataState = msg.payload.status;

    flow.set("sensorDataFreshness", dataState);
}

// Build dashboard status
if (connectionState === "OFFLINE") {

    msg.payload = "OFFLINE • DATA UNAVAILABLE";

}
else if (dataState === "STALE") {

    msg.payload = "ONLINE • DATA STALE";

}
else if (dataState === "FRESH") {

    msg.payload = "ONLINE • DATA FRESH";

}
else {

    msg.payload = "ONLINE • CHECKING";

}

return msg;

// System Health Calculator

let sensorConnection =
    flow.get("sensorConnectionState") || "OFFLINE";

let sensorData =
    flow.get("sensorDataFreshness") || "UNKNOWN";

let weatherStale =
    flow.get("weatherIsStale") || false;


// =====================================================
// SENSOR CONNECTION STATUS
// =====================================================

if (msg.topic === "team10/flood/zone1/node_status") {

    sensorConnection =
        (msg.payload === "online")
            ? "ONLINE"
            : "OFFLINE";

    flow.set("sensorConnectionState", sensorConnection);
}


// =====================================================
// SENSOR DATA FRESHNESS
// =====================================================

else if (
    msg.topic === "freshness_check" &&
    msg.payload &&
    msg.payload.status
) {

    sensorData = msg.payload.status;

    flow.set("sensorDataFreshness", sensorData);
}


// =====================================================
// WEATHER FRESHNESS
// =====================================================

else if (
    msg.payload &&
    typeof msg.payload.weather_stale === "boolean"
) {

    weatherStale = msg.payload.weather_stale;

    flow.set("weatherIsStale", weatherStale);
}


// =====================================================
// OVERALL SYSTEM HEALTH
// =====================================================

const degraded =
    sensorConnection === "OFFLINE" ||
    sensorData === "STALE" ||
    weatherStale === true;


msg.payload = degraded
    ? "SYSTEM DEGRADED"
    : "SYSTEM HEALTHY";


return msg;

const form = msg.payload;

if (!form || !form.location || !form.issue_type || !form.description) {
    node.warn("Citizen Report Handler: incomplete form submission");
    return null;
}

const report = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    location: String(form.location).trim().slice(0, 120),
    issue_type: String(form.issue_type).trim(),
    description: String(form.description).trim().slice(0, 500),
    status: "Reported",
    time: new Date().toLocaleString()
};

const PHOTO_WINDOW_MS = 10 * 60 * 1000;
const pendingPhoto = flow.get("pendingReportPhoto");
if (pendingPhoto && (Date.now() - pendingPhoto.ts) < PHOTO_WINDOW_MS) {
    report.photo = pendingPhoto.dataUrl;
}
flow.set("pendingReportPhoto", null);

let reports = flow.get("citizenReports") || [];
reports.unshift(report);
if (reports.length > 50) reports = reports.slice(0, 50);
flow.set("citizenReports", reports);

msg.payload = reports;
msg.report = report;
return msg;

// Report Confirmation Message
const report = msg.report;

msg.payload = report
    ? "Thanks! Your report (" + report.issue_type + " at " + report.location + ") has been received."
    : "Thanks! Your report has been received.";

return msg;

const report = msg.report;

if (!report) {
    return null;
}

const email = {
    subject: "New Drain Issue Reported: " + report.issue_type + " (" + report.location + ")"
};

if (report.photo) {
    email.attachments = [
        { filename: "report-photo.jpg", path: report.photo }
    ];
}

msg.email = email;

msg.payload =
    "A citizen has reported a drain issue.\n\n" +
    "Location: " + report.location + "\n" +
    "Issue type: " + report.issue_type + "\n" +
    "Description: " + report.description + "\n" +
    "Reported at: " + report.time +
    (report.photo ? "\n\n(Photo attached)" : "");

return msg;

// Citizen Status Formatter
// Builds the plain-language status card for the public Citizen Dashboard.
// Fires on two different triggers, both wired in manually:
//   1) Risk State Output  -> msg.payload is the state string ("NORMAL"/"WATCH"/"ALERT"/"CRITICAL")
//   2) Weather Decision Input -> msg.payload is the weather decision object
// Either trigger refreshes the card using the latest known values of both.

let state;

if (typeof msg.payload === "string") {
    state = msg.payload;
} else {
    state = flow.get("currentRiskState") || "NORMAL";
}

const weather = flow.get("weatherForecast") || {};

const messages = {
    NORMAL:   { headline: "All Clear",       detail: "No flooding risk right now. Drains are operating normally.",                              color: "green"  },
    WATCH:    { headline: "Being Monitored", detail: "Weather is being watched closely. No action needed yet.",                                  color: "blue"   },
    ALERT:    { headline: "Elevated Risk",   detail: "Drains may overflow soon. Avoid parking or lingering near drains in this area.",            color: "orange" },
    CRITICAL: { headline: "High Flood Risk", detail: "Flooding is likely or already happening. Avoid this area and follow local advisories.",     color: "red"    }
};

const info = messages[state] || messages.NORMAL;

msg.payload = {
    state: state,
    headline: info.headline,
    detail: info.detail,
    color: info.color,
    rain_expected: !!weather.rain_expected_6h,
    rain_probability: weather.rain_probability_6h ?? 0,
    updated: new Date().toLocaleTimeString()
};

return msg;

// Store Pending Photo
// Holds an uploaded photo in flow context until the report form is
// submitted. The File Upload widget and the report form are two
// separate widgets, so their messages arrive separately - this
// bridges them together.

const MAX_BYTES = 5 * 1024 * 1024; // 5MB - the dashboard's default upload limit

if (!msg.payload || !msg.file) {
    return null;
}

if (msg.file.size > MAX_BYTES) {
    node.warn("Citizen photo upload rejected: too large (" + msg.file.size + " bytes)");
    msg.payload = "That photo is too large. Please choose one under 5MB.";
    return msg;
}

const dataUrl = "data:" + msg.file.type + ";base64," + msg.payload.toString("base64");

flow.set("pendingReportPhoto", {
    dataUrl: dataUrl,
    name: msg.file.name,
    ts: Date.now()
});

msg.payload = "Photo attached. Now fill out and submit the form below.";
return msg;

// Float Switch Handler
// A physical float switch is a hard "water is here" signal, so when
// it trips it locks the whole system at CRITICAL until it clears -
// see the matching override block added to Water Risk Classifier.
//
// If your ESP32 uses a different topic, edit the MQTT input node above.

const raw = msg.payload;

// Accepts common formats: 1/0, true/false, "1"/"0", "WET"/"DRY", "HIGH"/"LOW"
const tripped =
    raw === true ||
    raw === 1 ||
    raw === "1" ||
    String(raw).toLowerCase() === "true" ||
    String(raw).toLowerCase() === "wet" ||
    String(raw).toLowerCase() === "high";

flow.set("floatSwitchTripped", tripped);

if (!tripped) {
    // Just clears the lock - the next normal sensor reading
    // re-evaluates the real state on its own.
    return null;
}

node.warn("Float switch tripped - forcing CRITICAL");

msg.payload = { state: "CRITICAL" };
return msg;
